const $ = (q, root = document) => root.querySelector(q);
const content = $('#content');
const icons = {
 grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',
 chart:'<path d="M4 3v17h17M8 16v-5M13 16V7M18 16V4"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
 settings:'<path d="M18.98 9.87 L21.06 10.40 L21.06 13.60 L18.98 14.13 L18.45 15.43 L19.54 17.28 L17.28 19.54 L15.43 18.45 L14.13 18.98 L13.60 21.06 L10.40 21.06 L9.87 18.98 L8.57 18.45 L6.72 19.54 L4.46 17.28 L5.55 15.43 L5.02 14.13 L2.94 13.60 L2.94 10.40 L5.02 9.87 L5.55 8.57 L4.46 6.72 L6.72 4.46 L8.57 5.55 L9.87 5.02 L10.40 2.94 L13.60 2.94 L14.13 5.02 L15.43 5.55 L17.28 4.46 L19.54 6.72 L18.45 8.57 Z"/><circle cx="12" cy="12" r="3.2"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',left:'<path d="m15 5-7 7 7 7"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-5"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
 trend:'<path d="m3 17 6-6 4 4 7-9M14 6h6v6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 video:'<rect x="3" y="6" width="12" height="12" rx="2"/><path d="m15 10 6-3v10l-6-3"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',history:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6M12 7v5l3 2"/>',
 edit:'<path d="m15 4 5 5-12 12H3v-5L15 4ZM13 6l5 5"/>',archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8M10 12h4"/>'
};
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.grid}</svg>`;
const logos = {
 mail:'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285f4" d="M2 6v13h4V9Z"/><path fill="#34a853" d="m18 9 4-3v13h-4Z"/><path fill="#fbbc04" d="m18 5 4-3v4l-4 3Z"/><path fill="#ea4335" d="M2 2v4l10 8L22 6V2L12 10Z"/><path fill="#c5221f" d="m2 2 4 3v4L2 6Z"/></svg>',
 calendar:'<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285f4" d="M3 3h18v15l-3 3H3Z"/><path fill="#fff" d="M6 6h12v12H6Z"/><path fill="#1a73e8" d="M3 3h18v3H3ZM18 18h3l-3 3Z"/><path fill="#34a853" d="M3 18h15v3H3Z"/><path fill="#fbbc04" d="M18 6h3v12h-3Z"/><text x="12" y="15" text-anchor="middle" font-size="8" font-weight="bold" fill="#4285f4">31</text></svg>',
 analytics:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="16" y="2" width="6" height="20" rx="3" fill="#f9ab00"/><rect x="8" y="9" width="6" height="13" rx="3" fill="#e37400"/><circle cx="3" cy="19" r="3" fill="#e37400"/></svg>',
 search:'<img src="assets/google-g.svg" width="24" height="24" alt="Google">',
 zoom:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="1" y="1" width="22" height="22" rx="6" fill="#2d8cff"/><rect x="5" y="8" width="9" height="8" rx="2" fill="white"/><path d="m15 10 4-2v8l-4-2Z" fill="white"/></svg>'
};
const shortcutServices=shortcuts.map(s=>({...s,icon:s.id}));
shortcuts.forEach(s=>logos[s.id]='<img src="'+s.logo+'" width="24" height="24" alt="'+s.name+'">');
const services = [
 {id:'gmail',name:'Gmail',desc:'重要邮件，一目了然',icon:'mail',url:'https://mail.google.com/mail/u/0/',foot:'轻松管理每一封邮件'},
 {id:'calendar',name:'Google Calendar',desc:'为每件重要的事留出时间',icon:'calendar',url:'https://calendar.google.com/',foot:'让日程井然有序'},
 {id:'analytics',name:'Google Analytics',desc:'用数据，发现新的可能',icon:'analytics',url:'https://analytics.google.com/',foot:'洞察每一步增长'},
 {id:'search',name:'Google Search',desc:'好奇心的下一站',icon:'search',url:'https://www.google.com/',foot:'探索更广阔的世界'},
 {id:'zoom',name:'Zoom',desc:'下一场会议，一键抵达',icon:'zoom',url:'https://zoom.us/',foot:'随时进入你的会议'}
];
const escapeHtml = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readStorage(key, fallback) {try {const v=JSON.parse(localStorage.getItem('orbit:'+key));return v ?? fallback;} catch {return fallback;}}
function persist() {window.orbitDesktop?.syncMeetings(state.events).then(r=>{if(!r.ok)toast(r.error);});try{localStorage.setItem('orbit:state',JSON.stringify({mails:state.mails,events:state.events,history:state.history}));localStorage.setItem('orbit:prefs',JSON.stringify(prefs));}catch{toast('浏览器存储不可用，本次更改仅保留在当前会话。');}}
let today = new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateObject = (str) => new Date(`${str}T12:00:00`);
const toDateKey = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
let currentDate=dateObject(today);
const seedMails = [];
const seedEvents = [];
const stored=readStorage('state',{});
const state={page:'overview',mails:Array.isArray(stored.mails)?stored.mails:seedMails,events:Array.isArray(stored.events)?stored.events:[],history:Array.isArray(stored.history)?stored.history:[],mailFilter:'all',mailQuery:'',chartPeriod:7,calendarDate:new Date(currentDate),calendarView:'month'};
const prefs={language:'en',density:'comfortable',weekStart:'monday',fontScale:80,timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',...readStorage('prefs',{})};
if(prefs.fontScaleVersion!==2){const previous=readStorage('prefs',{});prefs.fontScale=previous.fontScale===undefined?80:Number(previous.fontScale)*.4;}prefs.fontScaleVersion=2;
prefs.fontScale=Number.isFinite(Number(prefs.fontScale))?Math.min(125,Math.max(50,Number(prefs.fontScale))):80;
try{prefs.timeZone=OrbitTime.normalize(prefs.timeZone);}catch{prefs.timeZone='UTC';}
function applyTimeZone(zone){prefs.timeZone=OrbitTime.normalize(zone);today=OrbitTime.dateKey(new Date(),prefs.timeZone);currentDate=dateObject(today);for(const e of state.events){if(!e.startAt){try{e.startAt=OrbitTime.localInstant(e.date,e.time,e.timeZone||'Asia/Shanghai');}catch{continue;}}e.date=OrbitTime.dateKey(e.startAt,prefs.timeZone);e.time=OrbitTime.clock(e.startAt,prefs.timeZone);e.timeZone=prefs.timeZone;}}
applyTimeZone(prefs.timeZone);
const browserPages={};
let browserNavigation={canGoBack:false,canGoForward:false};
const notificationReads=new Set(readStorage('notificationReads',[]));
function saveUiPreferences(){try{localStorage.setItem('orbit:prefs',JSON.stringify(prefs));}catch{toast('本次界面设置仅保留在当前会话。');}}
function applySidebarState(){const collapsed=!!prefs.sidebarCollapsed;document.body.classList.toggle('sidebar-collapsed',collapsed);$('#sidebar').inert=collapsed;const button=$('#sidebar-toggle');button.setAttribute('aria-expanded',String(!collapsed));button.setAttribute('aria-label',collapsed?'展开侧栏':'收起侧栏');button.title=collapsed?'展开侧栏':'收起侧栏';OrbitI18n.apply(document.querySelector('.app-titlebar'),prefs.language);}
function toggleSidebar(){prefs.sidebarCollapsed=!prefs.sidebarCollapsed;applySidebarState();saveUiPreferences();syncNativeView();}
function notificationsList(){const entries=[];const gmail=liveSummary.gmail;const events=[...(liveSummary.calendar?.events||[]),...state.events.filter(e=>e.date===today)];if(gmail?.status==='success'&&gmail.count>0)entries.push({id:JSON.stringify([today,'gmail',gmail.count,(gmail.mails||[]).map(m=>m.id||m.subject).sort()]),title:gmail.count+' 封今日未读邮件'});if(events.length)entries.push({id:JSON.stringify([today,'calendar',events.map(e=>[e.id,e.title,e.startAt||e.date,e.time]).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b)))]),title:'今天有 '+events.length+' 项日程'});return entries.map(n=>({...n,read:notificationReads.has(n.id)}));}
function updateNotificationBadge(){const count=notificationsList().filter(n=>!n.read).length;$('.notification-dot').hidden=count===0;const button=$('[data-action="notifications"]');button.setAttribute('aria-label',count?'查看通知，'+count+' 条未读':'查看通知，无未读');button.title=count?count+' 条未读通知':'没有未读通知';}
function notificationsModal(){const entries=notificationsList();openModal('今日动态','<div class="notification-actions"><button class="text-link" data-action="notifications-read-all" '+(entries.some(n=>!n.read)?'':'disabled')+'>全部已读</button></div>'+(entries.length?entries.map((n,i)=>'<button class="notification-row '+(n.read?'is-read':'is-unread')+'" data-action="notification-read" data-id="'+escapeHtml(n.id)+'"><span class="notification-read-dot"></span><span>'+escapeHtml(n.title)+'</span><small>'+(n.read?'已读':'标为已读')+'</small></button>').join(''):'<p class="notifications-empty">暂无通知</p>'));}
function markNotificationsRead(id){const entries=notificationsList();for(const n of id===undefined?entries:entries.filter(n=>n.id===id))notificationReads.add(n.id);const recent=[...notificationReads].slice(-200);notificationReads.clear();recent.forEach(id=>notificationReads.add(id));try{localStorage.setItem('orbit:notificationReads',JSON.stringify(recent));}catch{toast('已读状态仅保留在当前会话。');}updateNotificationBadge();notificationsModal();}
function applyNavigationSpacing(value=prefs.navigationSpacing){const spacing=Math.max(-20,Math.min(24,Number(value)||0));document.documentElement.style.setProperty('--nav-spacing',spacing+'px');document.documentElement.style.setProperty('--nav-row-padding',(13+Math.min(0,spacing)/2)+'px');document.documentElement.style.setProperty('--nav-row-gap',Math.max(0,spacing)+'px');}
function applyFontScale(value=prefs.fontScale){document.documentElement.style.setProperty('--ui-scale',Math.min(125,Math.max(50,Number(value)||80))/50);}

let liveSummary={gmail:{status:'not_connected'},calendar:{status:'not_connected'}};
let summaryLoading=false;
let futureMeetings={status:"not_connected",events:[]};let meetingsLoading=false;
async function refreshMeetings(){if(!window.orbitDesktop||meetingsLoading)return;meetingsLoading=true;if(state.page==='zoom')render();try{futureMeetings=await window.orbitDesktop.getMeetings();if(futureMeetings.ok===false)futureMeetings={status:"error",error:futureMeetings.error,events:[]};}catch{futureMeetings={status:"error",error:"无法读取预约会议。",events:[]};}finally{meetingsLoading=false;if(state.page==='zoom')render();}}
function validateZoom(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&(u.hostname==='zoom.us'||u.hostname.endsWith('.zoom.us')||u.hostname==='zoom.com'||u.hostname.endsWith('.zoom.com'))&&/^\/(?:j|my|wc\/join)\/[^/]+\/?$/.test(u.pathname);}catch{return false;}}
function findEvent(id){return state.events.find(e=>e.id===id)||futureMeetings.events?.find(e=>e.id===id)||liveSummary.calendar?.events?.find(e=>e.id===id);}
function summaryStatistic(value,unit){return '<div class="summary-stat"><div class="metric-value">'+value+'<span class="metric-unit">'+unit+'</span></div></div>';}
function mailSummaryContent(){const g=liveSummary.gmail;if(g?.status==='success')return g.mails.length?g.mails.map(m=>'<a class="mail-preview" href="#gmail"><span class="sender-avatar blue">'+escapeHtml(m.initial)+'</span><div class="mail-info"><div class="mail-line"><span class="sender-name">'+escapeHtml(m.sender)+'</span><span class="mail-time">'+escapeHtml(m.time)+'</span></div><div class="mail-subject">'+escapeHtml(m.subject)+'</div></div><span class="unread-dot"></span></a>').join(''):'<div class="summary-empty">'+icon('mail')+'<strong>今日没有未读邮件</strong><p>让收件箱，保持轻盈。</p></div>';return '<div class="summary-empty">'+icon('mail')+'<strong>重要消息，一处掌握</strong><p>'+escapeHtml(g?.status==='error'?g.error:'连接 Google 账号后，这里显示今天收到的未读邮件。')+'</p><button class="secondary-btn" data-action="account">连接 Google '+icon('arrow')+'</button></div>';}
function updateConnectionLabel(){const el=$('.demo-indicator');el.innerHTML='<span></span>'+(liveSummary.connected?'Google 已连接':'Google 未连接');el.classList.toggle('is-connected',!!liveSummary.connected);$('.profile small').textContent=liveSummary.connected?'Google 已授权':'个人工作空间';}
async function refreshSummary(){if(!window.orbitDesktop||summaryLoading)return;summaryLoading=true;if(state.page==='overview')render();try{const result=await window.orbitDesktop.getSummary();if(result.ok===false)throw new Error(result.error);liveSummary=result;if(result.date){today=result.date;currentDate=dateObject(today);}}catch{toast('暂时无法刷新数据，请稍后重试。');}finally{summaryLoading=false;render();}}
function nativePage(id){return '<section id="native-web-surface" class="native-web-surface"><div class="native-loading"></div></section>';}
function isNativePage(id=state.page){return navigationItem(id)?.custom===true||['pdf','browser','gmail','calendar','analytics','search','chatgpt',...shortcuts.map(s=>s.id)].includes(id)||!!browserPages[id];}
function updatePageActions(){$('#page-actions').innerHTML=isNativePage()?'<button class="icon-btn" data-action="native-back" '+(browserNavigation.canGoBack?'':'disabled')+' aria-label="网页后退" title="后退">'+icon('left')+'</button><button class="icon-btn" data-action="native-forward" '+(browserNavigation.canGoForward?'':'disabled')+' aria-label="网页前进" title="前进">'+icon('chevron')+'</button><button class="icon-btn" data-action="reload-native" aria-label="刷新网页" title="刷新">'+icon('history')+'</button>':'';}
function syncNativeView(){document.body.classList.toggle('native-page',isNativePage());if(!window.orbitDesktop)return;if(document.querySelector('#modal').open){window.orbitDesktop.showService(null);return;}requestAnimationFrame(()=>{const surface=$('#native-web-surface');if(!surface){window.orbitDesktop.showService(null);return;}const r=surface.getBoundingClientRect();window.orbitDesktop.showService(state.page,{x:Math.round(r.x),y:Math.round(r.y),width:Math.round(r.width),height:Math.round(r.height)}).then(result=>{if(result.navigation){browserNavigation=result.navigation;updatePageActions();OrbitI18n.apply($('#page-actions'),prefs.language);}});});}
window.addEventListener('resize',syncNativeView);
function acceptBrowserPage(page){if(!page?.id)return;if(page.navigation)browserNavigation=page.navigation;if($('#modal').open)closeModal();browserPages[page.id]=page;state.page=page.id;history.replaceState(null,'','#'+page.id);$('#sidebar').classList.remove('open');render();}
async function openWebsite(url){if(!window.orbitDesktop){toast('请在桌面版中打开网页。');return;}const result=await window.orbitDesktop.openWebsite(url);if(!result.ok)toast(result.error);else acceptBrowserPage(result);}
function zoomPage(){const remote=(futureMeetings.events||[]).filter(e=>e.zoomLink);const meetings=[...remote,...state.events.filter(e=>e.zoomLink&&Date.parse(e.startAt)>Date.now())].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return heading('A MEETING AWAY','你的会议，一键抵达。','','<div class="meeting-tools"><button class="secondary-btn" data-action="refresh-meetings">'+icon('history')+(meetingsLoading?'正在同步…':'同步预约')+'</button><button class="primary-btn" data-action="new-event">'+icon('plus')+'添加会议</button></div>')+'<div class="zoom-banner"><span class="service-logo zoom">'+logos.zoom+'</span><div><strong>从安排，到见面。</strong><p>保存 Zoom 邀请链接，点击即可打开客户端。也可以通过应用内加入。</p></div><a class="secondary-btn" href="https://zoom.us/meeting#/upcoming" target="_blank" rel="noopener noreferrer">Zoom 预约 '+icon('external')+'</a></div><div class="zoom-meetings">'+(meetings.length?meetings.map(e=>'<section class="meeting-card"><div class="meeting-date">'+icon('calendar')+escapeHtml(e.date)+'<span>'+escapeHtml(e.time)+' · '+e.duration+' 分钟</span></div><h2>'+escapeHtml(e.title)+'</h2><p>'+escapeHtml(e.remote?(e.calendarName||'Google Calendar')+(e.recurring?' · 重复会议，下一场':'')+(e.responseStatus==='needsAction'?' · 待回复邀请':e.responseStatus==='accepted'?' · 已接受':''):e.location||'本地会议')+'</p><div class="meeting-actions"><button class="primary-btn" data-action="join-zoom" data-id="'+escapeHtml(e.id)+'" data-mode="app">'+icon('video')+'打开 Zoom</button><button class="secondary-btn" data-action="join-zoom" data-id="'+escapeHtml(e.id)+'" data-mode="browser">应用内加入</button><button class="icon-btn" data-action="view-event" data-id="'+escapeHtml(e.id)+'" aria-label="会议详情">'+icon('chevron')+'</button></div></section>').join(''):'<section class="panel zoom-empty"><span class="service-logo zoom">'+logos.zoom+'</span><h2>'+ (meetingsLoading?'正在同步预约':futureMeetings.status==='not_connected'?'连接 Google 查看预约':futureMeetings.status==='error'?'预约读取失败':'没有即将开始的 Zoom 会议')+'</h2><p>'+escapeHtml(futureMeetings.error||futureMeetings.errors?.join('；')||'读取所有 Google 日历中的未来安排与邀请。')+'</p><button class="primary-btn" data-action="'+(futureMeetings.status==='not_connected'?'account':'new-event')+'">'+(futureMeetings.status==='not_connected'?'连接 Google':icon('plus')+'添加会议')+'</button></section>')+'</div>'+((futureMeetings.errors||[]).length?'<p class="login-warning">'+escapeHtml(futureMeetings.errors.join('；'))+'</p>':'')+'<p class="dashboard-note">“打开 Zoom”需要电脑已安装 Zoom。个人会议室链接可使用“应用内加入”。会议链接与口令仅保存在本机。</p>';}
async function joinZoom(id,mode){const e=findEvent(id);if(!e?.zoomLink||!validateZoom(e.zoomLink)){toast('此日程没有有效的 Zoom 会议链接。');return;}if(!window.orbitDesktop){window.open(e.zoomLink,'_blank','noopener,noreferrer');return;}const result=await window.orbitDesktop.joinZoom(e.zoomLink,mode||'app');toast(result.ok?(mode==='browser'?'已在应用内打开会议。':'已向 Zoom 客户端发送加入请求。'):result.error);}
async function connectionChoice(){await connectionModal();}
async function connectionModal(){window.orbitDesktop?.showService(null);const c=await window.orbitDesktop.getConnection();openModal('连接你的 Google', '<div class="modal-note">原生网页可直接登录使用。首页的真实汇总另外通过 Google 官方 API 读取，需要你自己的桌面应用 OAuth 配置。授权在系统浏览器完成，仅请求只读权限。</div><form data-form="connection"><label for="google-client">Desktop OAuth Client ID</label><input id="google-client" name="clientId" value="'+escapeHtml(c.clientId||'')+'" placeholder="…apps.googleusercontent.com" required><label for="google-secret">OAuth Client Secret（如配置文件提供）</label><input id="google-secret" type="password" name="clientSecret" autocomplete="off" placeholder="'+(c.hasSecret?'已保存，留空可保留':'仅保存在本机，使用 Windows 加密')+'"><div class="connection-help">在 Google Cloud 创建“桌面应用”OAuth 客户端，并启用 Gmail API、Calendar API。测试模式请把自己添加为测试用户。</div><div class="modal-actions"><button type="submit" class="secondary-btn">保存配置</button><button type="button" class="primary-btn" data-action="connect-google">'+(c.connected?'重新授权':'连接 Google')+'</button></div>'+(c.connected?'<div class="disconnect-row"><button type="button" class="text-link" data-action="disconnect-google">断开首页汇总授权</button><small>此操作不会退出原生网页。</small></div>':'')+'</form>');}
async function saveConnection(form,f){const r=await window.orbitDesktop.saveConnection({clientId:f.get('clientId'),clientSecret:f.get('clientSecret')});if(!r.ok){toast(r.error);return false;}toast('连接配置已保存。');return true;}
async function beginGoogleConnection(){const form=$('form[data-form="connection"]');if(form){if(!form.reportValidity())return;if(!await saveConnection(form,new FormData(form)))return;}toast('请在系统浏览器完成 Google 授权。');const r=await window.orbitDesktop.connectGoogle();if(!r.ok){toast(r.error);return;}closeModal();refreshSummary();refreshMeetings();}
async function disconnectGoogle(){const r=await window.orbitDesktop.disconnectGoogle();if(!r.ok){toast(r.error);return;}closeModal();futureMeetings={status:"not_connected",events:[]};await refreshSummary();toast('首页汇总授权已断开。');}
$('#modal').addEventListener('close',()=>{applyNavigationSpacing();applyFontScale();syncNativeView();});

let toastTimer;
function toast(message){$('#toast').textContent=OrbitI18n.text(message,prefs.language);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function injectIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function unreadCount(){return liveSummary.gmail?.status==='success'?liveSummary.gmail.count:0;}
function renderNav(){renderWorkspaceNavigation();}
function render(){applyFontScale();applyNavigationSpacing();applySidebarState();document.body.classList.toggle('desktop',!!window.orbitDesktop);document.body.classList.toggle('overview-page',state.page==='overview');renderNav();$('#page-name').textContent=(navigationItem(state.page)?displayNavigationName(navigationItem(state.page)):null)||({...Object.fromEntries(shortcuts.map(s=>[s.id,s.name])),overview:'概览',gmail:'Gmail',calendar:'日历',analytics:'Analytics',search:'Google 搜索',chatgpt:'ChatGPT',zoom:'Zoom 会议'})[state.page]||browserPages[state.page]?.title||'网页';document.title=`${$('#page-name').textContent} · Orbit`;document.body.classList.toggle('compact',prefs.density==='compact');content.innerHTML=({...Object.fromEntries(shortcuts.map(s=>[s.id,()=>nativePage(s.id)])),overview:overviewPage,gmail:()=>nativePage('gmail'),calendar:()=>nativePage('calendar'),analytics:()=>nativePage('analytics'),search:()=>nativePage('search'),chatgpt:()=>nativePage('chatgpt'),zoom:zoomPage})[state.page]?.()||nativePage(state.page);updatePageActions();injectIcons(content);syncNativeView();updateConnectionLabel();updateNotificationBadge();OrbitI18n.apply(document.body,prefs.language);}
function heading(eyebrow,title,subtitle,right=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle ? `<p>${subtitle}</p>` : ''}</div>${right}</div>`;}
function dateBadge(){if(prefs.language==='en')return '<div class="date-badge">'+icon('calendar')+new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric',weekday:'long'}).format(currentDate)+'</div>';return `<div class="date-badge">${icon('calendar')}${currentDate.getFullYear()} 年 ${currentDate.getMonth()+1} 月 ${currentDate.getDate()} 日 <span>·</span> ${['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][currentDate.getDay()]}</div>`;}
function searchForm(id,placeholder){return `<form class="hero-search" data-form="search" id="${id}">${icon('search')}<input type="search" name="query" aria-label="Google 搜索" placeholder="${placeholder}" autocomplete="off" required><span class="keycap">⌘ / Ctrl K</span><button type="submit" class="icon-btn" aria-label="搜索 Google">${icon('arrow')}</button></form>`;}
function servicesGrid(){return `<div class="service-grid">${services.map(s=>`<a class="service-card" href="#${s.id}"><div class="service-head"><span class="service-logo ${s.icon}">${logos[s.icon]}</span><span class="service-arrow">${icon('external')}</span></div><h3>${s.name}</h3></a>`).join('')}</div>`;}
function mailPreview(m){return `<button class="mail-preview" data-action="read-mail" data-id="${m.id}"><span class="sender-avatar ${m.color}">${escapeHtml(m.initial)}</span><div class="mail-info"><div class="mail-line"><span class="sender-name">${escapeHtml(m.sender)}</span><span class="mail-time">${escapeHtml(m.time)}</span></div><div class="mail-subject">${escapeHtml(m.subject)}</div></div>${m.unread?'<span class="unread-dot"></span>':''}</button>`;}
function schedulePreview(e){return '<div class="schedule-item"><span class="schedule-time">'+escapeHtml(e.time)+'</span><span class="schedule-line '+(e.type||'blue')+'"></span><span class="schedule-text"><strong>'+escapeHtml(e.title)+'</strong><small>'+icon(e.zoomLink?'video':'pin')+escapeHtml(e.zoomLink?'Zoom 会议':e.location||'未设置地点')+'</small></span>'+(e.zoomLink?'<button class="join-mini" data-action="join-zoom" data-id="'+escapeHtml(e.id)+'" data-mode="app">加入 '+icon('arrow')+'</button>':'<button class="icon-btn" data-action="view-event" data-id="'+escapeHtml(e.id)+'" aria-label="查看日程详情">'+icon('chevron')+'</button>')+'</div>';}
function overviewPage(){
 const hour=Number(OrbitTime.clock(new Date(),prefs.timeZone).slice(0,2));
 const greeting=hour<12?'上午好':hour<18?'下午好':'晚上好';
 const liveEvents=liveSummary.calendar?.status==='success'?liveSummary.calendar.events:[];
 const local=state.events.filter(e=>e.date===today);
 const items=[...liveEvents,...local].sort((a,b)=>a.time.localeCompare(b.time));
 const unread=liveSummary.gmail?.status==='success'?liveSummary.gmail.count:'—';
 const eventCount=liveSummary.calendar?.status==='success'?items.length:local.length||'—';
 const scheduleContent=items.length?items.slice(0,6).map(schedulePreview).join(''):'<div class="summary-empty">'+icon('calendar')+'<strong>'+(liveSummary.calendar?.status==='success'?'今天暂时没有安排':'让今天的安排，一目了然')+'</strong><p>'+(liveSummary.calendar?.status==='success'?'留一些时间，给自己。':'连接 Google 账号查看日程，或添加本地会议。')+'</p><button class="secondary-btn" data-action="new-event">'+icon('plus')+'添加会议</button></div>';
 const schedulePanel='<section class="panel summary-panel" data-summary="calendar"><div class="panel-top"><div class="panel-title">'+icon('calendar')+'<h2>今日日程</h2></div>'+summaryStatistic(eventCount,'项')+'</div>'+'<div class="summary-content schedule-list">'+scheduleContent+'</div></section>';
 const mailPanel='<section class="panel summary-panel" data-summary="gmail"><div class="panel-top"><div class="panel-title">'+icon('mail')+'<h2>今日未读邮件</h2></div>'+summaryStatistic(unread,'封')+'</div>'+'<div class="summary-content">'+mailSummaryContent()+'</div></section>';
 return heading('YOUR GOOGLE, ALL TOGETHER',greeting+'，开启你的节奏。','',dateBadge())+'<div class="section-top"><h2>今日汇总</h2><div class="summary-refresh"><button class="text-link" data-action="refresh-summary">'+icon('history')+(summaryLoading?'正在刷新…':'刷新数据')+'</button><span class="last-updated">'+(liveSummary.updatedAt?'更新于 '+OrbitTime.clock(liveSummary.updatedAt,prefs.timeZone):'尚未更新')+'</span></div></div><div class="two-columns summary-grid">'+schedulePanel+mailPanel+'</div>'+'<div class="section-top"><h2>我的应用</h2><button class="text-link" data-action="account">连接与管理 '+icon('arrow')+'</button></div>'+servicesGrid();
}
function gmailPage(){return heading('LESS NOISE, MORE CLARITY','收件箱','让重要的信息，得到恰好的关注。',`<button class="primary-btn" data-action="compose">${icon('edit')}写邮件</button>`)+`<div class="toolbar"><div class="tabs" aria-label="邮件筛选">${[['all','全部邮件'],['unread','未读'],['starred','星标'],['draft','草稿'],['archived','已归档']].map(([v,t])=>`<button class="tab ${state.mailFilter===v?'active':''}" data-action="mail-filter" data-filter="${v}" aria-pressed="${state.mailFilter===v}">${t}${v==='draft'?` (${state.mails.filter(m=>m.draft).length})`:''}</button>`).join('')}</div><input class="filter-input" id="mail-search" type="search" placeholder="搜索发件人或主题…" aria-label="搜索邮件" value="${escapeHtml(state.mailQuery)}"></div><section class="panel"><div class="panel-top"><div class="panel-title">${logos.mail}<h2>Gmail</h2><span class="label-tag">本地演示</span></div><a class="text-link" href="https://mail.google.com/" target="_blank" rel="noopener noreferrer">打开 Gmail ${icon('external')}</a></div><div id="mail-list">${mailRows()}</div><div class="mail-footer">演示邮件与草稿保存在当前浏览器。实际收发邮件请打开 Gmail。</div></section>`;}
function filteredMails(){return state.mails.filter(m=>{const f=state.mailFilter;const cat=f==='draft'?m.draft:f==='archived'?m.archived:!m.archived&&!m.draft&&(f==='unread'?m.unread:f==='starred'?m.starred:true);return cat&&`${m.sender} ${m.subject} ${m.preview||''}`.toLowerCase().includes(state.mailQuery.toLowerCase());});}
function mailRows(){const mails=filteredMails();return mails.length?mails.map(m=>`<div class="mail-table-row ${m.unread?'unread':''}" data-action="read-mail" data-id="${m.id}" role="button" tabindex="0" aria-label="阅读 ${escapeHtml(m.subject)}"><button class="star-btn ${m.starred?'starred':''}" data-action="star" data-id="${m.id}" aria-label="${m.starred?'取消星标':'添加星标'}" aria-pressed="${!!m.starred}">${m.starred?'★':'☆'}</button><span class="sender-avatar ${m.color}">${escapeHtml(m.initial)}</span><span class="sender-name">${escapeHtml(m.sender)}</span><span class="mail-subject">${escapeHtml(m.subject)}</span>${m.unread?'<span class="unread-dot"></span>':''}<span class="mail-time">${escapeHtml(m.time)}</span></div>`).join(''):'<div class="list-empty">这里很安静。<br>没有符合条件的邮件。</div>';}
function bindMailFilter(){$('#mail-search').addEventListener('input',e=>{state.mailQuery=e.target.value;$('#mail-list').innerHTML=mailRows();});}
function calendarPage(){const d=state.calendarDate,year=d.getFullYear(),month=d.getMonth();let start=new Date(year,month,1);const weekMonday=prefs.weekStart==='monday';const shift=day=>weekMonday?(day+6)%7:day;if(state.calendarView==='week')start=new Date(d);start.setDate(start.getDate()-shift(start.getDay()));const days=state.calendarView==='week'?7:42;const weekdays=weekMonday?['周一','周二','周三','周四','周五','周六','周日']:['周日','周一','周二','周三','周四','周五','周六'];let cells='';for(let i=0;i<days;i++){const day=new Date(start);day.setDate(day.getDate()+i);const key=toDateKey(day);const events=state.events.filter(e=>e.date===key).sort((a,b)=>a.time.localeCompare(b.time));cells+=`<div class="calendar-cell ${day.getMonth()!==month?'outside':''} ${key===today?'today':''}" data-action="new-event-date" data-date="${key}" role="button" tabindex="0" aria-label="${key}，${events.length} 项日程"><span class="day-number">${day.getDate()}</span>${events.map(e=>`<button class="calendar-event ${e.type}" data-action="view-event" data-id="${escapeHtml(e.id)}">${escapeHtml(e.time)} ${escapeHtml(e.title)}</button>`).join('')}</div>`;}return heading('MAKE ROOM FOR WHAT MATTERS','你的时间，井然有序。','为协作、灵感和深度工作，留出空间。',`<button class="primary-btn" data-action="new-event">${icon('plus')}新建日程</button>`)+`<div class="toolbar"><div class="calendar-head"><strong>${year} 年 ${month+1} 月</strong><button class="icon-btn" data-action="calendar-prev" aria-label="上一周期">${icon('left')}</button><button class="icon-btn" data-action="calendar-next" aria-label="下一周期">${icon('chevron')}</button><button class="secondary-btn" data-action="calendar-today">今天</button></div><div class="tabs"><button class="tab ${state.calendarView==='month'?'active':''}" data-action="calendar-view" data-view="month">月</button><button class="tab ${state.calendarView==='week'?'active':''}" data-action="calendar-view" data-view="week">周</button><a class="secondary-btn" href="https://calendar.google.com/" target="_blank" rel="noopener noreferrer">Google Calendar ${icon('external')}</a></div></div><section class="panel"><div class="calendar-grid">${weekdays.map(w=>`<div class="weekday">${w}</div>`).join('')}${cells}</div><div class="calendar-key"><span><i></i>工作与协作</span><span><i></i>会议</span><span><i></i>个人时间</span><span style="margin-left:auto">本地日程 · 北京时间</span></div></section>`;}
function searchPage(){const history=state.history.slice(0,6);return heading('FOLLOW YOUR CURIOSITY','探索，从一个问题开始。','世界很大，下一份灵感就在这里。')+`<section class="search-page"><div class="search-logo google-colors" aria-label="Google"><span>G</span><span>o</span><span>o</span><span>g</span><span>l</span><span>e</span></div><p class="search-description">保持好奇，发现更多。</p>${searchForm('google-search','你想探索什么？')}<div class="search-buttons"><button class="primary-btn" data-action="search-submit">Google 搜索${icon('arrow')}</button><a class="secondary-btn" href="https://artsandculture.google.com/" target="_blank" rel="noopener noreferrer">发现艺术与文化 ${icon('external')}</a></div><div class="search-bottom"><div class="section-top"><h2>${history.length?'最近的搜索':'灵感起点'}</h2>${history.length?'<button class="text-link" data-action="clear-history">清除记录</button>':''}</div><div class="search-chips">${(history.length?history:['简约设计','城市建筑','本周科技新闻','灵感与创意']).map(q=>`<button class="search-chip" data-action="search-chip" data-query="${escapeHtml(q)}">${icon(history.length?'history':'search')}${escapeHtml(q)}</button>`).join('')}</div><p class="search-notice">搜索结果将在 Google 新标签页打开。搜索记录仅保存在你的浏览器。</p></div></section>`;}
function openModal(title,body,userTitle=false){window.orbitDesktop?.showService(null);$('#modal-content').innerHTML=`<div class="modal-head"><h2 ${userTitle?'data-user-content':''}>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();OrbitI18n.apply(document.body,prefs.language);}
function closeModal(){$('#modal').close();applyNavigationSpacing();applyFontScale();syncNativeView();}
function accountModal(){if(window.orbitDesktop){connectionChoice();return;}openModal('Google 连接','<div class="modal-note">真实账号连接和原生网页集成在 Windows 桌面版中提供。此浏览器预览只展示工作台界面。</div>');}
function settingsModal(){openModal('设置与偏好',`<form data-form="settings"><div class="preference"><label for="ui-language">界面语言</label><select id="ui-language" name="language"><option value="zh" ${prefs.language!=='en'?'selected':''}>中文</option><option value="en" ${prefs.language==='en'?'selected':''}>English</option></select></div><div class="font-preference"><label for="ui-font-scale">界面字号 <output id="font-scale-value">${prefs.fontScale}%</output></label><input id="ui-font-scale" name="fontScale" type="range" min="50" max="125" step="5" value="${prefs.fontScale}"><div class="font-scale-labels"><span>50%</span><span>125%</span></div></div><div class="font-preference"><label for="navigation-spacing">导航标签间距 <output id="navigation-spacing-value">${prefs.navigationSpacing||0} px</output></label><input id="navigation-spacing" name="navigationSpacing" type="range" min="-20" max="24" step="1" value="${prefs.navigationSpacing||0}"><div class="font-scale-labels"><span>紧密</span><span>宽松</span></div></div><div class="preference"><span>界面密度</span><select name="density" aria-label="界面密度"><option value="comfortable" ${prefs.density==='comfortable'?'selected':''}>舒适</option><option value="compact" ${prefs.density==='compact'?'selected':''}>紧凑</option></select></div><div class="preference"><span>每周第一天</span><select name="weekStart" aria-label="每周第一天"><option value="monday" ${prefs.weekStart==='monday'?'selected':''}>周一</option><option value="sunday" ${prefs.weekStart==='sunday'?'selected':''}>周日</option></select></div><div class="preference"><label for="calendar-time-zone">日历时区</label><select id="calendar-time-zone" name="timeZone">${OrbitTime.zones.map(([label,value])=>'<option value="'+value+'" '+(prefs.timeZone===value?'selected':'')+'>'+label+'</option>').join('')}<option value="custom" ${OrbitTime.offset(prefs.timeZone)!==null?'selected':''}>自定义 UTC 偏移</option></select></div><div id="custom-zone-field" ${OrbitTime.offset(prefs.timeZone)===null?'hidden':''}><label for="custom-zone-offset">UTC 偏移</label><input id="custom-zone-offset" name="utcOffset" value="${OrbitTime.offset(prefs.timeZone)!==null?prefs.timeZone.replace('UTC',''):'+08:00'}" placeholder="+08:00 / -05:00 / +05:30"></div><p class="connection-help">美加地区自动适用夏令时；自定义 UTC 为固定偏移。</p><p class="search-notice">关闭主界面后，程序自动留在系统托盘中，日程开始前 5 分钟弹出提醒。右键托盘图标选择“退出程序”可完全退出。</p><div class="preference"><span>常用网站登录</span><button type="button" class="text-link" data-action="login-settings">密码与自动登录 ${icon('arrow')}</button></div><div class="preference"><span>本机数据 API</span><button type="button" class="text-link" data-action="api-settings">文本与后台操作 ${icon('arrow')}</button></div><div class="modal-actions"><button type="submit" class="primary-btn">保存设置</button></div></form>`);}
function readMail(id){const m=state.mails.find(m=>String(m.id)===String(id));if(!m)return;if(m.draft){composeModal(m);return;}m.unread=false;persist();render();openModal(escapeHtml(m.subject),`<div class="read-mail-meta"><span class="sender-avatar ${m.color}">${escapeHtml(m.initial)}</span><span><strong>${escapeHtml(m.sender)}</strong><small>${escapeHtml(m.email)} · ${escapeHtml(m.time)}</small></span></div><div class="read-mail-body">${escapeHtml(m.body)}</div><div class="modal-actions" style="margin-top:25px"><button class="secondary-btn" data-action="archive-mail" data-id="${m.id}">${icon('archive')}${m.archived?'移回收件箱':'归档'}</button><button class="primary-btn" data-action="reply" data-id="${m.id}">${icon('edit')}回复草稿</button></div>`,true);}
function composeModal(draft=null,reply=null){const target=draft?.email||reply?.email||'';openModal(draft?'编辑草稿':reply?'回复邮件':'新邮件',`<div class="modal-note">演示模式 · 此表单保存本地草稿。实际发送请使用 Gmail。</div><form data-form="compose" data-id="${draft?.id||''}"><label for="compose-to">收件人</label><input id="compose-to" type="email" name="to" placeholder="name@example.com" value="${escapeHtml(target)}" required><label for="compose-subject">主题</label><input id="compose-subject" name="subject" placeholder="一个清晰的主题" value="${escapeHtml(draft?.subject|| (reply?'Re: '+reply.subject:''))}" required><label for="compose-body">正文</label><textarea id="compose-body" name="body" placeholder="写下你想分享的内容…" required>${escapeHtml(draft?.body||'')}</textarea><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">取消</button><button type="submit" class="primary-btn">保存草稿</button></div></form>`);}
function eventModal(date=today,event=null){openModal(event?'编辑日程':'新建日程',`<div class="modal-note">本地会议保存在本机。粘贴 Zoom 邀请链接后，即可一键加入；此表单不会创建 Zoom 房间或同步 Google Calendar。</div><form data-form="event" data-id="${event?.id||''}"><label for="event-title">日程名称</label><input id="event-title" name="title" placeholder="为重要的事留出时间" value="${escapeHtml(event?.title||'')}" required maxlength="100"><div class="form-row"><div><label for="event-date">日期</label><input id="event-date" type="date" name="date" value="${escapeHtml(event?.date||date)}" required></div><div><label for="event-time">开始时间</label><input id="event-time" type="time" name="time" value="${event?.time||'09:00'}" required></div></div><div class="form-row"><div><label for="event-duration">时长（分钟）</label><input id="event-duration" type="number" name="duration" min="5" max="1440" step="5" value="${event?.duration||30}" required></div><div><label for="event-type">分类</label><select id="event-type" name="type">${[['green','工作与协作'],['blue','会议'],['orange','个人时间']].map(([v,t])=>`<option value="${v}" ${event?.type===v?'selected':''}>${t}</option>`).join('')}</select></div></div><label for="event-location">地点</label><input id="event-location" name="location" placeholder="会议室、线上会议或其他地点" value="${escapeHtml(event?.location||'')}"><label for="event-zoom">Zoom 会议链接</label><input id="event-zoom" type="url" name="zoomLink" placeholder="https://us02web.zoom.us/j/…" value="${escapeHtml(event?.zoomLink||'')}" maxlength="2048"><label for="event-notes">备注</label><textarea id="event-notes" name="notes" placeholder="补充日程内容…" style="min-height:75px">${escapeHtml(event?.notes||'')}</textarea><div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">取消</button><button type="submit" class="primary-btn">${event?'保存更改':'创建日程'}</button></div></form>`);}
function viewEvent(id){const e=findEvent(id);if(!e)return;openModal(escapeHtml(e.title),'<div class="event-body"><div>'+icon('calendar')+escapeHtml(e.date)+' · '+escapeHtml(e.time)+' · '+e.duration+' 分钟</div><div>'+icon('pin')+escapeHtml(e.location||'未设置地点')+'</div><p style="white-space:pre-wrap">'+escapeHtml(e.notes||'暂无备注')+'</p></div>'+(e.zoomLink?'<div class="zoom-join-box"><span class="service-logo zoom">'+logos.zoom+'</span><div><strong>Zoom 会议</strong><small>从工作台直接进入会议</small></div><button class="primary-btn" data-action="join-zoom" data-id="'+escapeHtml(e.id)+'" data-mode="app">打开 Zoom</button><button class="secondary-btn" data-action="join-zoom" data-id="'+escapeHtml(e.id)+'" data-mode="browser">应用内加入</button></div>':'<div class="modal-note">此日程未添加 Zoom 链接。</div>')+(e.remote?'<div class="modal-actions"><a href="'+escapeHtml(e.htmlLink||'https://calendar.google.com/')+'" target="_blank" rel="noopener noreferrer" class="primary-btn">在 Google Calendar 编辑 '+icon('external')+'</a></div>':'<div class="modal-actions"><button class="secondary-btn" data-action="delete-event" data-id="'+escapeHtml(e.id)+'">删除会议</button><button class="primary-btn" data-action="edit-event" data-id="'+escapeHtml(e.id)+'">'+icon('edit')+'编辑会议</button></div>'),true);}
function searchGoogle(query){const q=query.trim().slice(0,500);if(!q)return;state.history=[q,...state.history.filter(v=>v!==q)].slice(0,12);persist();const url='https://www.google.com/search?q='+encodeURIComponent(q);if(window.orbitDesktop)window.orbitDesktop.openWebsite(url).then(r=>{if(!r.ok)toast(r.error);});else window.open(url,'_blank','noopener,noreferrer');if(state.page==='search')render();toast('已在应用内打开 Google 搜索。');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const id=el.dataset.id;switch(el.dataset.action){
 case 'account':accountModal();break;case 'api-settings':apiSettingsModal();break;case 'copy-api':copyApiConfig(el.dataset.kind);break;case 'rotate-api':configureApi({rotate:true});break;case 'calendar-write':enableCalendarWrite();break;case 'refresh-meetings':refreshMeetings();break;case 'refresh-summary':refreshSummary();break;case 'join-zoom':joinZoom(id,el.dataset.mode);break;case 'connect-google':case 'connect-google-default':beginGoogleConnection();break;case 'edit-google-config':connectionModal();break;case 'disconnect-google':disconnectGoogle();break;case 'native-back':window.orbitDesktop?.navigateWebsite(state.page,'back');break;case 'native-forward':window.orbitDesktop?.navigateWebsite(state.page,'forward');break;case 'reload-native':window.orbitDesktop?.reloadService(state.page);break;case 'settings':settingsModal();break;case 'login-settings':loginSettingsModal();break;case 'forget-login':forgetLogin(el.dataset.site);break;case 'close-modal':closeModal();break;
 case 'new-navigation':navigationModal();break;case 'navigation-icon':pickNavigationIcon();break;case 'navigation-icon-default':if(navigationDraft){navigationDraft.iconData='';updateNavigationPreview();}break;case 'menu':$('#sidebar').classList.toggle('open');break;
 case 'notifications':notificationsModal();break;case 'notifications-read-all':markNotificationsRead();break;case 'notification-read':markNotificationsRead(el.dataset.id);break;case 'toggle-sidebar':toggleSidebar();break;
 case 'read-mail':readMail(id);break;case 'compose':composeModal();break;
 case 'reply':composeModal(null,state.mails.find(m=>String(m.id)===id));break;
 case 'star':{e.stopPropagation();const m=state.mails.find(m=>String(m.id)===id);if(m){m.starred=!m.starred;persist();render();}break;}
 case 'archive-mail':{const m=state.mails.find(m=>String(m.id)===id);if(m){m.archived=!m.archived;persist();closeModal();render();toast(m.archived?'邮件已归档至本地归档箱。':'邮件已移回收件箱。');}break;}
 case 'mail-filter':state.mailFilter=el.dataset.filter;render();break;
 
 case 'calendar-prev':case 'calendar-next':{const step=el.dataset.action==='calendar-next'?1:-1;if(state.calendarView==='week')state.calendarDate.setDate(state.calendarDate.getDate()+7*step);else state.calendarDate=new Date(state.calendarDate.getFullYear(),state.calendarDate.getMonth()+step,1);render();break;}
 case 'calendar-today':state.calendarDate=new Date(currentDate);render();break;
 case 'calendar-view':state.calendarView=el.dataset.view;render();break;
 case 'new-event':eventModal();break;case 'new-event-date':eventModal(el.dataset.date);break;
 case 'view-event':viewEvent(id);break;case 'edit-event':eventModal(today,findEvent(id));break;
 case 'delete-event':state.events=state.events.filter(e=>e.id!==id);persist();closeModal();render();toast('本地日程已删除。');break;
 case 'search-submit':$('#google-search')?.requestSubmit();break;case 'search-chip':searchGoogle(el.dataset.query);break;
 case 'clear-history':state.history=[];persist();render();toast('搜索记录已清除。');break;
 }});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=new FormData(form);switch(form.dataset.form){case 'navigation':await saveNavigationForm(form,f);break;case 'search':searchGoogle(f.get('query'));break;
 case 'compose':{const existing=state.mails.find(m=>String(m.id)===form.dataset.id);const m={id:existing?.id||Date.now(),sender:'我 · 草稿',initial:'U',email:f.get('to'),subject:f.get('subject'),body:f.get('body'),preview:f.get('body').slice(0,50),time:'刚刚',color:'green',draft:true,unread:false,starred:existing?.starred||false};if(existing)Object.assign(existing,m);else state.mails.unshift(m);persist();closeModal();state.mailFilter='draft';location.hash='gmail';render();toast('草稿已保存到当前浏览器。');break;}
 case 'event':{const existing=state.events.find(e=>e.id===form.dataset.id);const event={id:existing?.id||'e'+Date.now(),title:f.get('title'),date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')),type:f.get('type'),location:f.get('location'),notes:f.get('notes'),zoomLink:(f.get('zoomLink')||'').trim()};if(event.zoomLink&&!validateZoom(event.zoomLink)){toast('请输入有效的 HTTPS Zoom 会议邀请链接。');return;}try{event.startAt=OrbitTime.localInstant(event.date,event.time,prefs.timeZone);event.timeZone=prefs.timeZone;}catch(error){toast(error.message);return;}if(existing)Object.assign(existing,event);else state.events.push(event);state.calendarDate=dateObject(event.date);persist();closeModal();render();toast(existing?'日程已更新。':'日程已保存，开始前 5 分钟会提醒你。');break;}
 case 'api-settings':configureApi({enabled:f.has('enabled')});break;case 'connection':saveConnection(form,f);break;case 'login-settings':saveLoginPreferences(f);break;
 case 'settings':{let zone;try{zone=OrbitTime.normalize(f.get('timeZone')==='custom'?f.get('utcOffset'):f.get('timeZone'));}catch(error){toast(error.message);return;}if(window.orbitDesktop){const r=await window.orbitDesktop.saveTimeZone(zone);if(!r.ok){toast(r.error);return;}}const language=f.get('language')==='en'?'en':'zh';if(window.orbitDesktop){const result=await window.orbitDesktop.saveLanguage(language);if(!result.ok){toast(result.error);return;}}prefs.language=language;applyTimeZone(zone);futureMeetings={status:'loading',events:[]};prefs.navigationSpacing=Math.max(-20,Math.min(24,Number(f.get('navigationSpacing'))||0));prefs.fontScale=Number(f.get('fontScale'));prefs.density=f.get('density');prefs.weekStart=f.get('weekStart');persist();closeModal();render();toast('偏好设置已保存。');refreshSummary();refreshMeetings();break;}
 }});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#modal').open)return;const input=$('.hero-search input');if(input)input.focus();else{location.hash='search';requestAnimationFrame(()=>$('.hero-search input')?.focus());}}if(e.key==='Enter'&&e.target.matches('[role="button"][data-action]')){e.preventDefault();e.target.click();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
function route(){const page=location.hash.slice(1);state.page=['overview','gmail','calendar','analytics','search','chatgpt','zoom',...shortcuts.map(s=>s.id)].includes(page)||navigationItem(page)||browserPages[page]?page:'overview';$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);if(state.page==='zoom')refreshMeetings();}
window.orbitDesktop?.onOpenPage(acceptBrowserPage);
document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(link&&/^https?:/i.test(link.getAttribute('href'))){e.preventDefault();openWebsite(link.href);}},true);
document.addEventListener('input',e=>{if(e.target.id==='ui-font-scale'){$('#font-scale-value').textContent=e.target.value+'%';applyFontScale(e.target.value);}});
window.addEventListener('hashchange',route);injectIcons();route();if(window.orbitDesktop){Promise.all([window.orbitDesktop.getTimeZone(),window.orbitDesktop.getLocalEvents()]).then(([r,saved])=>{if(saved.initialized)state.events=saved.events;if(r.language)prefs.language=r.language;if(r.timeZone)applyTimeZone(r.timeZone);if(!saved.initialized)window.orbitDesktop.syncMeetings(state.events);render();refreshSummary();});}setInterval(()=>{if(!document.querySelector('#modal').open){if(state.page==='overview')refreshSummary();if(state.page==='zoom')refreshMeetings();}},300000);

async function loginSettingsModal(){if(!window.orbitDesktop){openModal('登录记忆','<p>此功能在 Windows 桌面版中提供。</p>');return;}const c=await window.orbitDesktop.getLoginSettings();openModal('密码与自动登录','<div class="modal-note">首次在 HTTPS 网站填写账号密码并点击登录后，应用使用 Windows 加密保存在本机。新增网址也会记住；下次自动填入并尝试登录。验证码、二次验证和特殊登录流程需要手动完成。</div>'+(!c.encryptionAvailable||c.loadFailed?'<p class="login-warning">'+(c.loadFailed?'现有登录信息无法解密，可清除后重新保存。':'Windows 加密暂时不可用，密码不会保存。')+'</p>':'')+'<form data-form="login-settings"><div class="preference"><label class="checkbox-label"><input type="checkbox" name="remember" '+(c.remember?'checked':'')+'>记住网站账号密码</label></div><div class="preference"><label class="checkbox-label"><input type="checkbox" name="autoLogin" '+(c.autoLogin?'checked':'')+'>自动填入后尝试登录</label></div><div class="saved-logins">'+c.sites.map(site=>'<div class="saved-login"><span><strong>'+escapeHtml(site.name)+'</strong><small>'+escapeHtml(site.saved?site.username:'尚未保存')+'</small></span>'+(site.saved?'<button type="button" class="text-link" data-action="forget-login" data-site="'+escapeHtml(site.id)+'">删除密码</button>':'')+'</div>').join('')+'</div><div class="modal-actions"><button type="button" class="secondary-btn" data-action="forget-login" data-site="all">清除全部密码</button><button type="submit" class="primary-btn">保存设置</button></div></form>');}
async function saveLoginPreferences(f){const r=await window.orbitDesktop.saveLoginSettings({remember:f.has('remember'),autoLogin:f.has('autoLogin')});if(r.ok){closeModal();toast('登录偏好已保存。');}else toast(r.error);}
async function forgetLogin(id){const r=await window.orbitDesktop.forgetLogin(id);if(r.ok){await loginSettingsModal();toast('已删除保存的登录信息。');}else toast(r.error);}

document.addEventListener('change',e=>{if(e.target.id==='calendar-time-zone')$('#custom-zone-field').hidden=e.target.value!=='custom';});

async function apiSettingsModal(){if(!window.orbitDesktop)return;const c=await window.orbitDesktop.getApiStatus();openModal('本机数据 API','<div class="modal-note">AI 客户端可读取数据文本，在后台管理日程。网页内容只导出文本；网站内部功能仍由其官方 API 决定。</div><form data-form="api-settings"><div class="preference"><label class="checkbox-label"><input type="checkbox" name="enabled" '+(c.enabled?'checked':'')+'>开启本机 API</label></div><div class="api-address">'+escapeHtml(c.url||OrbitI18n.text(c.error||'服务已关闭',prefs.language))+'</div><div class="modal-actions"><button type="button" class="secondary-btn" data-action="copy-api" data-kind="api">复制 API 配置</button><button type="button" class="secondary-btn" data-action="copy-api" data-kind="mcp">复制 MCP 配置</button></div><div class="preference"><span>Google 日历写入</span>'+(c.calendarWrite?'<span>已授权</span>':'<button type="button" class="text-link" data-action="calendar-write">启用写入授权</button>')+'</div><p class="connection-help">邮件、日历、会议、已打开网页的文本，以及本地日程增删改。Google 日历写入需另行授权；普通 ChatGPT 网页无法直接访问本机，需要支持本地 MCP 的客户端。</p><div class="modal-actions"><button type="button" class="secondary-btn" data-action="rotate-api">重置访问令牌</button><button type="submit" class="primary-btn">保存设置</button></div></form>');}
async function configureApi(input){const r=await window.orbitDesktop.saveApiSettings(input);if(r.error)toast(r.error);else{await apiSettingsModal();toast('API 设置已保存。');}}
async function copyApiConfig(kind){const r=await window.orbitDesktop.copyApiConfig(kind);toast(r.ok?'连接配置已复制。':r.error);}
async function enableCalendarWrite(){toast('请在系统浏览器完成 Google 日历写入授权。');const r=await window.orbitDesktop.connectGoogle({calendarWrite:true});if(!r.ok){toast(r.error);return;}await apiSettingsModal();refreshSummary();refreshMeetings();}
window.orbitDesktop?.onEventsChanged(events=>{state.events=events;applyTimeZone(prefs.timeZone);try{localStorage.setItem('orbit:state',JSON.stringify({mails:state.mails,events:state.events,history:state.history}));}catch{}if(!$('#modal').open)render();});
window.orbitDesktop?.onDataChanged(()=>{refreshSummary();refreshMeetings();});

loadNavigation();




document.addEventListener('input',e=>{if(e.target.id==='navigation-spacing'){$('#navigation-spacing-value').textContent=e.target.value+' px';applyNavigationSpacing(e.target.value);}});
